local hCamera = CMND_LOAD_CAMERA(cameraName, "data/chr/motion/waza/vma0001.pck|vma0001_cam.xv");
local hTelop = CMND_CREATE_CHARA(7, telopName, "data/chr/motion/waza/vma0001/vma0001_telop.xc", "Effect");
WaitLoading(hCamera);
WaitLoading(hTelop);
CMND_SET_ENABLE(hTelop, true);
CMND_SET_ANTIALIASE(0, 1);
CMND_PUSH_CAMERA(hCamera);
CMND_BRIGHT_FADE(SCREEN_A, 0.0, 60.0);
CMND_SET_MOTION(hCamera, "01", 3, 0);
// ... wait for the motion ...
StartBrightFade(SCREEN_A, -1.0, 60.0);
CMND_POP_CAMERA();
CMND_SET_ANTIALIASE(0, 0);
CMND_DELETE_CHARA(hTelop);
CMND_DELETE_CAMERA(hCamera);
